const C={ground:'#384744',edge:'#63776e',orange:'#ffac62',purple:'#be9ce6',cream:'#fff0cd'};
export function rounded(c,x,y,w,h,r=8){c.beginPath();c.roundRect(x,y,w,h,r);}
export function prop(c,p){const {x,y,w=45,h=45,kind}=p;c.save();c.translate(x,y);c.shadowColor='#07131b99';c.shadowBlur=8;c.shadowOffsetY=6;
if(['house','shop','medical'].includes(kind)){c.fillStyle='#b2b1a0';rounded(c,-w,-h,w*2,h*1.7,4);c.fill();c.shadowBlur=0;c.fillStyle=kind==='medical'?'#72738b':'#607e7b';c.beginPath();c.moveTo(-w-7,-h+5);c.lineTo(0,-h-27);c.lineTo(w+7,-h+5);c.lineTo(w+7,0);c.lineTo(-w-7,0);c.fill();c.fillStyle='#efbd69';c.fillRect(-w+9,8,15,15);c.fillRect(w-24,8,15,15);c.fillStyle='#344541';c.fillRect(-7,10,14,h*.7);if(kind==='medical'){c.fillStyle='#bfe8c8';c.fillRect(-3,-h-8,6,20);c.fillRect(-10,-h-1,20,6);}}
else if(kind==='car'){c.fillStyle='#172329';rounded(c,-w,-h/2,w*2,h,10);c.fill();c.fillStyle='#708c9b';c.fillRect(-w/2,-h/2+4,w*.8,h-8);c.fillStyle='#f6cb70';c.fillRect(w-4,-h/2+3,5,8);c.fillRect(w-4,h/2-11,5,8);c.fillStyle='#090e12';for(const a of [-1,1])for(const b of [-1,1])c.fillRect(a*w*.65-6,b*h/2-4,12,9);}
else if(kind==='tree'){c.fillStyle='#65554b';c.fillRect(-4,0,8,30);for(const [dx,dy,r] of [[0,-9,24],[-15,3,19],[15,4,19]]){c.fillStyle=dx<0?'#75826a':'#84947b';c.beginPath();c.arc(dx,dy,r,0,7);c.fill();}}
else if(kind==='pumpkin'){c.shadowColor='#ef983d';c.shadowBlur=18;c.fillStyle='#c87536';c.beginPath();c.ellipse(0,0,16,13,0,0,7);c.fill();c.shadowBlur=0;c.fillStyle='#ffd78a';c.fillRect(-8,-4,5,5);c.fillRect(4,-4,5,5);c.fillRect(-5,5,10,3);}
else if(kind==='garden'){c.fillStyle='#85664f';rounded(c,-w,-h,w*2,h*2,4);c.fill();for(let i=0;i<3;i++)for(let j=0;j<3;j++){c.fillStyle='#9da777';c.beginPath();c.ellipse(-w+12+i*w*.65,-h+12+j*h*.65,8,5,.5,0,7);c.fill();}}
else if(kind==='play'){c.strokeStyle='#cfac69';c.lineWidth=6;c.beginPath();c.moveTo(-25,25);c.lineTo(-10,-25);c.lineTo(15,-25);c.lineTo(30,25);c.stroke();c.fillStyle='#88b7ad';c.beginPath();c.moveTo(-10,-25);c.lineTo(15,-25);c.lineTo(39,26);c.lineTo(10,26);c.fill();}
else{c.fillStyle=kind==='barrier'?'#8d8c77':'#9d7654';rounded(c,-w/2,-h/2,w,h,4);c.fill();c.strokeStyle='#d9ba7b';c.lineWidth=3;c.beginPath();c.moveTo(-w/2,-h/2);c.lineTo(w/2,h/2);c.moveTo(w/2,-h/2);c.lineTo(-w/2,h/2);c.stroke();}c.restore();}
export function person(c,a,t=0,bar=true){const dead=a.hp<=0;c.save();c.translate(a.x,a.y);if(dead){c.rotate(1.4);c.globalAlpha=.35;}const bob=dead?0:Math.sin(t*9+a.y)*1.2;c.fillStyle='#111a2590';c.beginPath();c.ellipse(0,13,15,6,0,0,7);c.fill();c.translate(0,bob);c.strokeStyle=a.side==='enemy'?'#697d65':'#273a48';c.lineWidth=6;c.beginPath();c.moveTo(-5,4);c.lineTo(-7,15);c.moveTo(5,4);c.lineTo(7,15);c.stroke();c.fillStyle=a.color||'#9eac81';rounded(c,-10,-12,20,23,6);c.fill();c.fillStyle=a.side==='enemy'?'#aab68a':'#d9bda1';c.beginPath();c.arc(0,-18,8,0,7);c.fill();c.strokeStyle=a.side==='enemy'?'#ac8b8a':'#e1bd81';c.lineWidth=3;c.beginPath();c.moveTo(7,-4);c.lineTo(a.side==='enemy'?17:a.range<60?-14:-25,-6);c.stroke();if(a.side!=='enemy'&&a.range<60){c.fillStyle=a.color;if(a.id==='mara')c.fillRect(-20,-14,12,9);else{c.strokeStyle='#e8e2cd';c.lineWidth=a.id==='rosa'?5:2;c.beginPath();c.moveTo(-14,-6);c.lineTo(-18,-22);c.stroke();}}if(a.shield>0){c.strokeStyle='#8bd2e2';c.lineWidth=2;c.beginPath();c.arc(0,-2,23,0,7);c.stroke();}if(a.stun>0||a.marked>0||a.slow>0){c.fillStyle='#e5b7ff';c.font='bold 16px sans-serif';c.fillText(a.stun>0?'✦':a.marked>0?'⌖':'❄',-7,-40);}c.restore();if(bar&&!dead){c.fillStyle='#101e28';c.fillRect(a.x-21,a.y-36,42,5);c.fillStyle=a.side==='enemy'?'#e58b7d':'#9be0b8';c.fillRect(a.x-21,a.y-36,42*Math.max(0,a.hp/a.maxHp),5);}}
export function paintScene(canvas,scene,battle=null,effects=[],time=0,shake=0){const c=canvas.getContext('2d');const W=900,H=560;c.clearRect(0,0,canvas.width,canvas.height);c.save();c.scale(canvas.width/W,canvas.height/H);c.fillStyle='#17232d';c.fillRect(0,0,W,H);c.save();if(shake){c.translate(Math.sin(time*65)*shake,Math.cos(time*51)*shake*.55);}const points=[[100,280],[260,58],[650,58],[810,280],[650,502],[260,502]];c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();c.fillStyle=C.ground;c.shadowColor='#030c16';c.shadowBlur=30;c.shadowOffsetY=12;c.fill();c.shadowBlur=0;c.shadowOffsetY=0;c.strokeStyle=C.edge;c.lineWidth=2;c.stroke();c.save();c.clip();const g=c.createLinearGradient(0,0,900,560);g.addColorStop(0,'#7977a638');g.addColorStop(1,'#18253666');c.fillStyle=g;c.fillRect(0,0,W,H);c.strokeStyle='#99a18d33';c.lineWidth=42;c.beginPath();c.moveTo(100,280);c.bezierCurveTo(340,240,500,335,810,280);c.stroke();scene.props.forEach(p=>prop(c,p));for(let i=0;i<7;i++){const x=180+i*96,y=430+Math.sin(i+time*.2)*10;const fog=c.createRadialGradient(x,y,0,x,y,80);fog.addColorStop(0,'#c2b6e00b');fog.addColorStop(1,'#c2b6e000');c.fillStyle=fog;c.fillRect(x-80,y-80,160,160);}c.restore();
c.fillStyle='#c3cfcc';c.font='12px sans-serif';c.fillText('← HIGH SCHOOL WAVES',112,288);c.fillStyle='#e6cf9f';c.fillText('HOME →',717,288);
if(battle){[...battle.allies,...battle.enemies.filter(e=>e.active)].sort((a,b)=>a.y-b.y).forEach(a=>person(c,a,time));for(const e of effects){const age=time-e.at;if(age<0||age>1.1)continue;c.globalAlpha=1-age/1.1;const color=e.type==='heal'?'#a4efbb':e.type==='headshot'?'#ffcf7e':e.type==='crit'?'#ffac70':e.type==='special'?'#d9b4ff':'#fff2d7';c.strokeStyle=color;c.lineWidth=e.type==='headshot'?3:1;if(age<.15){c.beginPath();c.moveTo(e.from.x,e.from.y);c.lineTo(e.x,e.y);c.stroke();}c.fillStyle=color;c.font=`bold ${['headshot','crit'].includes(e.type)?22:16}px sans-serif`;c.textAlign='center';const label=e.type==='headshot'?'HEADSHOT':e.type==='crit'?`CRIT ${e.amount}`:e.type==='heal'?`+${e.amount}`:e.type==='kill'?'':e.type==='wave'?'':e.type==='special'?'✦ '+e.amount:e.type==='shield'?'⛨ '+e.amount:String(e.amount);c.fillText(label,e.x,e.y-42-age*25);if(['crit','headshot','special'].includes(e.type)){c.beginPath();c.arc(e.x,e.y,8+age*30,0,7);c.stroke();}c.globalAlpha=1;c.textAlign='start';}}
c.restore();c.restore();}
export function heroPreview(canvas,h){const c=canvas.getContext('2d');c.fillStyle='#233842';c.fillRect(0,0,canvas.width,canvas.height);c.save();c.translate(canvas.width/2,canvas.height/2+10);c.scale(3,3);person(c,{...h,x:0,y:0,side:'ally',maxHp:h.hp},0,false);c.restore();}
